    ptReflectionOriginalVariantLookup=reinterpret_cast<PTReflectionVariantLookupFn>(base+0x1DD450);
    ptReflectionBindCompute=reinterpret_cast<PTReflectionBindComputeFn>(base+0x1DB750);
